SELECT * FROM torn_stock_monthly_state
WHERE effective_month >= #{startMonth}
  AND effective_month <= #{endMonth}
  AND state_status = 'CONFIRMED'
  AND deleted = 0
ORDER BY effective_month ASC, stocks_id ASC

SELECT s.* FROM ( SELECT ms.*, ROW_NUMBER() OVER ( PARTITION BY ms.stocks_id ORDER BY ms.effective_month DESC, ms.id DESC ) AS row_num FROM torn_stock_monthly_state ms WHERE ms.stocks_id IN
#{stocksId}
AND ms.effective_month < #{targetMonth} AND ms.state_status = 'CONFIRMED' AND ms.deleted = 0 ) s WHERE row_num = 1 ORDER BY s.stocks_id ASC
